{"explanation":"A secant line passes through two points on a curve: at x = a and x = a + h. As h approaches 0, the second point moves toward the first, and the secant’s slope approaches the derivative f′(a)—the slope of the tangent line. Drag the h slider to watch this happen.","manimCode":"const f = x => 0.3 * x * x;
const a = 0.7;
let h = 1.8;

const title = new Text({ text: 'Secant → Tangent', color: WHITE, fontSize: 34 });
title.moveTo([0, 3.35, 0]);

const ax = new Axes({
  xRange: [-3.2, 3.2, 1],
  yRange: [-2, 3.5, 1],
  xLength: 9,
  yLength: 5.3,
  tips: false
});
ax.moveTo([-1.1, -0.05, 0]);
const curve = ax.plot(f, { color: BLUE, xRange: [-3.2, 3.2] });

const makeSegment = (color, width) => {
  const p = new Polygon({ vertices: [ax.c2p(0, 0), ax.c2p(1, 0)], color });
  p.setStrokeWidth(width);
  p.setFillOpacity(0);
  return p;
};

const tangent = makeSegment(TEAL, 3);
const secant = makeSegment(YELLOW, 5);
const run = makeSegment(ORANGE, 2);
const rise = makeSegment(ORANGE, 2);
const pointA = new Dot({ point: ax.c2p(a, f(a)), color: TEAL });
const pointB = new Dot({ point: ax.c2p(a + h, f(a + h)), color: ORANGE });

function updateGeometry() {
  const slope = (f(a + h) - f(a)) / h;
  const tangentSlope = 0.6 * a;
  const left = -1.1;
  const right = 2.9;
  tangent.setVertices([
    ax.c2p(left, f(a) + tangentSlope * (left - a)),
    ax.c2p(right, f(a) + tangentSlope * (right - a))
  ]);
  secant.setVertices([
    ax.c2p(left, f(a) + slope * (left - a)),
    ax.c2p(right, f(a) + slope * (right - a))
  ]);
  run.setVertices([ax.c2p(a, f(a)), ax.c2p(a + h, f(a))]);
  rise.setVertices([ax.c2p(a + h, f(a)), ax.c2p(a + h, f(a + h))]);
  pointB.moveTo(ax.c2p(a + h, f(a + h)));
}
updateGeometry();

const formula = new MathTex({ latex: '\\lim_{h\\to 0}\\frac{f(a+h)-f(a)}{h}=f\'(a)' });
await formula.waitForRender();
formula.moveTo([-0.7, -3.35, 0]);

scene.add(ax);
await scene.play(new Write(title));
await scene.play(new Create(curve));
await scene.play(new AnimationGroup([
  new Create(tangent),
  new Create(secant),
  new FadeIn(pointA),
  new FadeIn(pointB)
]));
scene.add(run, rise);
await scene.play(new Write(formula));

const controls = new Controls(scene, { position: 'top-right', theme: 'dark', width: 240 });
controls.addSlider({
  label: 'h (point separation)',
  min: 0.02,
  max: 1.8,
  value: 1.8,
  step: 0.02,
  onChange: value => {
    h = value;
    updateGeometry();
  }
});

await scene.wait(999999);"}

